// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
        MockGlpManager gm = new MockGlpManager();
        // initialize via low-level call to avoid interface-typed mock arguments
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.initialize.selector,
                address(0x1111), // _sGlp (unused for ownership flows)
                address(0x2222), // _usdc
                address(0x3333), // _rewardRouter
                address(gm), // _glpManager: vault() queried during init
                address(0x4444), // _dnGmxJuniorVault
                address(this) // _keeper
            )
        );
        require(ok, "initialize failed");
    }

    function testFuzz_property(address newOwner) public {
        // current owner is address(this) (initialize caller); fuzzer supplies newOwner freely
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));

        c.transferOwnership(newOwner);

        assertTrue(c.owner() == newOwner, "ownership must transfer to newOwner");
    }
}

contract MockGlpManager {
    function vault() external pure returns (address) {
        return address(0x9999);
    }
}
